from pathlib import Path
s=Path('astra-remaining-improvements/stage/993e7c3b44d7');(s/'browser-tests').mkdir(exist_ok=True)
(s/'playwright.config.mjs').write_text('''import {defineConfig} from '@playwright/test';
const port=process.env.GLOBS_WEB_PORT||'4291';
export default defineConfig({testDir:'./browser-tests',workers:1,retries:0,timeout:90000,reporter:[['list'],['json',{outputFile:process.env.GLOBS_BROWSER_REPORT||'.verification/browser.json'}]],use:{baseURL:`http://127.0.0.1:${port}`,viewport:{width:1440,height:1100},trace:'retain-on-failure'},webServer:{command:`node node_modules/next/dist/bin/next start --hostname 127.0.0.1 --port ${port}`,url:`http://127.0.0.1:${port}/studio`,reuseExistingServer:false,timeout:90000}});
''',encoding='utf-8')
(s/'browser-tests/studio.spec.js').write_text('''import {test,expect} from '@playwright/test';
import {readFile} from 'node:fs/promises';
const token=process.env.GLOBS_AUTHOR_TOKEN,headers={Authorization:'Bearer '+token};
if(process.env.GLOBS_TEST_DATABASE!=='owned-temporary-cluster')throw new Error('Run npm run verify or the disposable database helper in browser mode.');
const draft=index=>({title:'Browser edition '+index,date:`2028-01-${String(index).padStart(2,'0')}`,locale:'en-US',rootLabel:'Engineering concepts',categories:Array.from({length:4},(_,i)=>({label:'Category '+i,hint:'',members:Array.from({length:4},(_,j)=>`Term ${i}-${j}`)}))});
async function create(request,index){const response=await request.post('/api/studio/puzzles',{headers,data:draft(index)});expect(response.status()).toBe(201);return response.json();}
async function login(page){await page.goto('/studio');await page.getByLabel('Author token').fill(token);await page.getByRole('button',{name:'Open workspace'}).click();await expect(page.getByRole('button',{name:'New puzzle'})).toBeVisible();}
async function fill(page,value){await page.getByLabel('Puzzle title',{exact:true}).fill(value.title);await page.getByLabel('Daily date').fill(value.date);await page.getByLabel('Final theme').fill(value.rootLabel);for(let i=0;i<4;i++){await page.getByLabel(`Category ${i+1} label`,{exact:true}).fill(value.categories[i].label);for(let j=0;j<4;j++)await page.getByLabel(`Category ${i+1} word ${j+1}`,{exact:true}).fill(value.categories[i].members[j]);}}
async function open(page,title){await page.getByLabel('Search titles').fill(title);await page.getByRole('button',{name:'Open '+title,exact:true}).click();await expect(page.getByLabel('Puzzle title',{exact:true})).toHaveValue(title);}
async function publish(request,puzzle){const response=await request.put('/api/studio/puzzles/'+puzzle.id+'/publication',{headers,data:{version:puzzle.version,published:true}});expect(response.status()).toBe(200);return response.json();}
test('HTTP author and public filter boundaries return explicit statuses',async({request})=>{expect((await request.get('/api/studio/puzzles')).status()).toBe(401);expect((await request.get('/api/studio/puzzles',{headers:{Authorization:'Bearer wrong'}})).status()).toBe(401);expect((await request.post('/api/studio/puzzles',{headers:{...headers,Origin:'http://unrelated.test'},data:draft(20)})).status()).toBe(403);for(const query of ['date=2026-02-30','size=mini&size=big','unknown=x'])expect((await request.get('/api/puzzles/daily?'+query)).status()).toBe(400);const bad=await request.post('/api/studio/puzzles',{headers,data:{...draft(20),unexpected:true}});expect(bad.status()).toBe(400);expect(bad.headers()['x-request-id']).toBeTruthy();});
test('studio creates, edits and publishes an immutable playable edition',async({page,request})=>{await login(page);await page.getByRole('button',{name:'New puzzle'}).click();await fill(page,draft(1));await page.getByRole('button',{name:'Save puzzle',exact:true}).click();await expect(page.getByRole('status')).toContainText('version 1');await page.getByLabel('Puzzle title',{exact:true}).fill('Browser revised edition');await page.getByRole('button',{name:'Save puzzle',exact:true}).click();await expect(page.getByRole('status')).toContainText('version 2');page.once('dialog',d=>d.accept());await page.getByRole('button',{name:'Publish puzzle',exact:true}).click();await expect(page.getByLabel('Puzzle title',{exact:true})).toBeDisabled();await expect(page.getByRole('status')).toContainText('published');const daily=await request.get('/api/puzzles/daily?date=2028-01-01');expect(daily.status()).toBe(200);expect((await daily.json()).title).toBe('Browser revised edition');await page.goto('/?date=2028-01-01');await expect(page.getByRole('heading',{name:'Browser revised edition'})).toBeVisible();});
test('stale studio editor retains and exports its draft before loading current',async({page,request})=>{const created=await create(request,2);await login(page);await open(page,created.title);await page.getByLabel('Puzzle title',{exact:true}).fill('My retained edit');const winner=await request.put('/api/studio/puzzles/'+created.id,{headers,data:{version:1,draft:{...created.draft,title:'Other author won'}}});expect(winner.status()).toBe(200);await page.getByRole('button',{name:'Save puzzle',exact:true}).click();await expect(page.getByRole('alert')).toContainText('changed');await expect(page.getByLabel('Puzzle title',{exact:true})).toHaveValue('My retained edit');const pending=page.waitForEvent('download');await page.getByRole('button',{name:'Export editor draft'}).click();expect(JSON.parse(await readFile((await (await pending).path()),'utf8')).draft.title).toBe('My retained edit');page.once('dialog',d=>d.accept());await page.getByRole('button',{name:'Load current puzzle'}).click();await expect(page.getByLabel('Puzzle title',{exact:true})).toHaveValue('Other author won');});
test('delete can be cancelled and confirmed; sign-out clears the token',async({page,request})=>{const created=await create(request,3);await login(page);await open(page,created.title);page.once('dialog',d=>d.dismiss());await page.getByRole('button',{name:'Delete draft'}).click();expect((await request.get('/api/studio/puzzles/'+created.id,{headers})).status()).toBe(200);page.once('dialog',d=>d.accept());await page.getByRole('button',{name:'Delete draft'}).click();await expect(page.getByRole('status')).toContainText('deleted');expect((await request.get('/api/studio/puzzles/'+created.id,{headers})).status()).toBe(404);await page.getByRole('button',{name:'Sign out'}).click();await expect(page.getByLabel('Author token')).toHaveValue('');expect(await page.evaluate(()=>Object.keys(localStorage).some(key=>/token/i.test(key)))).toBe(false);});
test('server failure preserves editor inputs and does not show save success',async({page,request})=>{const created=await create(request,4);await login(page);await open(page,created.title);await page.getByLabel('Puzzle title',{exact:true}).fill('Retained on outage');await page.route('**/api/studio/puzzles/'+created.id,route=>route.request().method()==='PUT'?route.fulfill({status:503,contentType:'application/json',body:JSON.stringify({error:'Database temporarily unavailable'})}):route.continue());await page.getByRole('button',{name:'Save puzzle',exact:true}).click();await expect(page.getByRole('alert')).toContainText('unavailable');await expect(page.getByLabel('Puzzle title',{exact:true})).toHaveValue('Retained on outage');expect((await (await request.get('/api/studio/puzzles/'+created.id,{headers})).json()).title).toBe(created.title);});
test('game saves a merge before displaying it and restores it after reload',async({page,request})=>{const created=await publish(request,await create(request,5));const puzzle=await (await request.get('/api/puzzles/daily?date=2028-01-05')).json();await page.goto('/?date=2028-01-05');await expect(page.getByRole('heading',{name:created.title})).toBeVisible();const a=puzzle.tiles[0],b=puzzle.tiles.find(t=>t.id!==a.id&&t.groupToken===a.groupToken);await page.getByRole('button',{name:a.label,exact:false}).click();await page.getByRole('button',{name:b.label,exact:false}).click();await expect.poll(()=>page.evaluate(id=>JSON.parse(localStorage.getItem('globs-session:'+id)||'null')?.snapshot.moveCount,puzzle.puzzleId)).toBe(1);await page.reload();await expect(page.getByRole('heading',{name:created.title})).toBeVisible();expect(await page.evaluate(id=>JSON.parse(localStorage.getItem('globs-session:'+id)).snapshot.board.length,puzzle.puzzleId)).toBe(15);});
test('corrupt session is preserved and exported before confirmed reset',async({page,request})=>{const created=await publish(request,await create(request,6));const key='globs-session:'+created.id;await page.addInitScript(({key})=>localStorage.setItem(key,'{broken game'),{key});await page.goto('/?date=2028-01-06');await expect(page.getByRole('heading',{name:'Recover saved game'})).toBeVisible();const download=page.waitForEvent('download');await page.getByRole('button',{name:'Export stored game'}).click();expect(await readFile((await (await download).path()),'utf8')).toBe('{broken game');page.once('dialog',d=>d.dismiss());await page.getByRole('button',{name:'Reset game',exact:true}).click();expect(await page.evaluate(key=>localStorage.getItem(key),key)).toBe('{broken game');page.once('dialog',d=>d.accept());await page.getByRole('button',{name:'Reset game',exact:true}).click();await expect(page.getByRole('heading',{name:created.title})).toBeVisible();});
test('quota failure keeps the accepted game board and exports pending move',async({page,request})=>{const created=await publish(request,await create(request,7));const puzzle=await (await request.get('/api/puzzles/daily?date=2028-01-07')).json();await page.goto('/?date=2028-01-07');await expect(page.getByRole('heading',{name:created.title})).toBeVisible();await page.evaluate(()=>{Storage.prototype.setItem=()=>{throw new DOMException('Quota exceeded','QuotaExceededError');};});const a=puzzle.tiles[0],b=puzzle.tiles.find(t=>t.id!==a.id&&t.groupToken===a.groupToken);await page.getByRole('button',{name:a.label,exact:false}).click();await page.getByRole('button',{name:b.label,exact:false}).click();await expect(page.getByRole('alert')).toContainText('Quota');await expect(page.getByRole('button',{name:a.label,exact:false})).toBeVisible();await expect(page.getByRole('button',{name:'Export pending move'})).toBeVisible();expect(await page.evaluate(id=>localStorage.getItem('globs-session:'+id),puzzle.puzzleId)).toBeNull();});
test('studio desktop and narrow forms stay within the page',async({page,request})=>{const created=await create(request,8);await login(page);await open(page,created.title);for(const [name,width,height]of [['desktop',1440,2300],['narrow',390,4200]]){await page.setViewportSize({width,height});await page.evaluate(()=>window.scrollTo(0,0));expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);await page.screenshot({path:`astraupskill/images/${name}.png`,fullPage:true});}});
''',encoding='utf-8');print('Added nine production-server Chromium scenarios')
